def distinct_proper_divisors(n):
    """Returns a list of distinct proper divisors of n excluding 1 and n."""
    divisors = []
    for i in range(2, n):
        if n % i == 0:
            divisors.append(i)
    return divisors

def is_nice(n):
    """Checks if a number n is nice."""
    divisors = distinct_proper_divisors(n)
    if not divisors:
        return False
    product = 1
    for d in divisors:
        product *= d
    return product == n

def find_nice_numbers(count):
    """Finds the first 'count' nice numbers and returns their sum."""
    nice_numbers = []
    num = 2  # Start from the smallest natural number greater than 1
    while len(nice_numbers) < count:
        if is_nice(num):
            nice_numbers.append(num)
        num += 1
    return sum(nice_numbers)

